package com.franco.desco.adapter.in.web.salesoperation;import io.swagger.v3.oas.annotations.media.Schema;import jakarta.validation.constraints.*;import java.time.Instant;import java.util.List;
public final class SalesOperationRequests{private SalesOperationRequests(){}@Schema(name="SalesOperationCreateRequest")public record Create(@NotNull Long campaniaVentaId,@NotBlank@Size(max=40)String codigo,@NotNull Instant fechaInicioProgramada,@NotNull Instant fechaFinProgramada,@Size(max=400)String observacion){}@Schema(name="SalesOperationUpdateRequest")public record Update(@NotNull Instant fechaInicioProgramada,@NotNull Instant fechaFinProgramada,@Size(max=400)String observacion){}@Schema(name="SalesOperationZonesRequest")public record Zones(@NotEmpty List<@NotNull Long>zonas){}@Schema(name="SalesOperationTransitionRequest")public record Transition(@Size(max=500)String motivo){} }
